
import PDFDocument from 'pdfkit';
import fs from 'fs';

const GEAR_IMAGE_BASE64 = 'data:image/jpeg;base64,'
// Função para formatar data no formato DD/MM/YYYY
function formatDatePtBR(date) {
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    return `${day}/${month}/${year}`;
}

type OrcamentoPdf = {
    id: string;
    numero: number;
    data: Date;
    cliente: string;
    cnpj: string;
    prazoEntrega: string;
    frete: string;
    condPagamento: string;
    items: Array<{
        quantidade: number;
        codCS: string;
        descricao: string;
        ncm: string;
        valorUnitario: number;
        total: number;
    }>;
    valorTotal: number;
    cfop?: string;
    valorIcms?: number;
    valorIpi?: number;
    valorIss?: number;
    observacao?: string;
    pdfPath?: string;
    createdAt: Date;
    updatedAt: Date;
}

export async function generatePdf(orcamento: OrcamentoPdf): Promise<Buffer> {
    return new Promise((resolve, reject) => {
        const doc = new PDFDocument({
            size: 'A4',
            margins: {
                top: 30,
                bottom: 30,
                left: 30,
                right: 30
            }
        });

        const buffers: Buffer[] = [];
        doc.on('data', buffers.push.bind(buffers));
        doc.on('end', () => {
            const pdfData = Buffer.concat(buffers);
            resolve(pdfData);
        });
        doc.on('error', reject);

        // --- Variáveis de Layout ---
        const pageLeftMargin = doc.page.margins.left;
        const pageRightMargin = doc.page.width - doc.page.margins.right;
        let currentY = doc.y;

        // --- Cabeçalho Azul ---
        const headerHeight = 125;
        doc.fillColor('#002e6e')
            .rect(0, 0, doc.page.width, headerHeight)
            .fill();

        // --- Logotipo ---
        if (GEAR_IMAGE_BASE64) {
            doc.image(GEAR_IMAGE_BASE64, 0, 0, {
                width: doc.page.width,
                height: headerHeight
            });
        }

        currentY = headerHeight + 20;

        // --- Informações da Empresa / Endereço / Detalhes do Orçamento ---
        doc.fillColor('black');
        const colWidth = (doc.page.width - pageLeftMargin - doc.page.margins.right - (2 * 10)) / 3;
        const blockPadding = 5;
        const lineHeight = 12;

        // Bloco 1: Informações da Empresa
        let block1X = pageLeftMargin;
        let block1Y = currentY;
        doc.font('Helvetica-Bold').fontSize(10);
        doc.text('SANTOS & CARDOSO LTDA', block1X + blockPadding, block1Y + blockPadding, {
            width: colWidth - (2 * blockPadding)
        });
        doc.font('Helvetica').fontSize(9);
        doc.text(`CNPJ-${'59.171.719/0001-38'}`, block1X + blockPadding, doc.y + 2, {
            width: colWidth - (2 * blockPadding)
        });
        doc.text(`Insc : ${'91122370-86'}`, block1X + blockPadding, doc.y + 2, {
            width: colWidth - (2 * blockPadding)
        });
        doc.text(`FONE ${'3272-5329 / 42 99931-4341'}`, block1X + blockPadding, doc.y + 2, {
            width: colWidth - (2 * blockPadding)
        });

        const block1Height = doc.y - block1Y + blockPadding + 5;

        // Bloco 2: Endereço
        let block2X = block1X + colWidth + 10;
        let block2Y = currentY;
        doc.font('Helvetica-Bold').fontSize(10);
        doc.text('Endereço:', block2X + blockPadding, block2Y + blockPadding, {
            width: colWidth - (2 * blockPadding)
        });
        doc.font('Helvetica').fontSize(9);
        doc.text('RUA AGUA MARINHA 112 - SOCOMIN TELEMACO BORBA- PARANA', block2X + blockPadding, doc.y + 2, {
            width: colWidth - (2 * blockPadding)
        });
        const block2Height = doc.y - block2Y + blockPadding + 5;

        // Bloco 3: Detalhes do Orçamento
        let block3X = block2X + colWidth + 10;
        let block3Y = currentY;
        doc.font('Helvetica-Bold').fontSize(10);
        doc.text('DATA:', block3X + blockPadding, block3Y + blockPadding, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.data ? formatDatePtBR(orcamento.data) : '')}`);
        doc.font('Helvetica-Bold').text('ORÇAMENTO:', block3X + blockPadding, doc.y + 2, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.numero)}`);
        doc.font('Helvetica-Bold').text('PRAZO ENTREGA:', block3X + blockPadding, doc.y + 2, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.prazoEntrega || '60 DIAS')}`);
        const block3Height = doc.y - block3Y + blockPadding + 5;

        function formatCurrency(value: number) {
            return value.toFixed(2)
                .replace('.', ',')
                .replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1.');
        }

        function safeText(value: any) {
            if (value === null || value === undefined) return '';
            return String(value);
        }

        // Desenhar bordas dos blocos
        const maxBlockHeight = Math.max(block1Height, block2Height, block3Height);
        doc.strokeColor('#ccc')
            .lineWidth(1)
            .rect(block1X, block1Y, colWidth, maxBlockHeight)
            .stroke();
        doc.rect(block2X, block2Y, colWidth, maxBlockHeight)
            .stroke();
        doc.rect(block3X, block3Y, colWidth, maxBlockHeight)
            .stroke();

        currentY = currentY + maxBlockHeight + 10;

        // --- Informações do Cliente ---
        let clientInfoY = currentY;
        const clientColWidth = (doc.page.width - doc.page.margins.left - doc.page.margins.right - (3 * 10)) / 4;

        doc.font('Helvetica-Bold').fontSize(10);
        doc.text('CLIENTE:', pageLeftMargin, clientInfoY + blockPadding, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.cliente)}`, {
            width: clientColWidth * 2 + 10,
            align: 'left'
        });

        doc.font('Helvetica-Bold').text('COND PAG:', pageLeftMargin + (clientColWidth * 2) + 20, clientInfoY + blockPadding, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.condPagamento || '30 DIAS')}`, {
            width: clientColWidth * 2,
            align: 'left'
        });

        doc.font('Helvetica-Bold').text('CNPJ:', pageLeftMargin, doc.y + 5, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.cnpj || '00.000.000/0000-00')}`);

        doc.font('Helvetica-Bold').text('FRETE:', pageLeftMargin + (clientColWidth * 2) + 20, doc.y - lineHeight, { continued: true });
        doc.font('Helvetica').text(` ${safeText(orcamento.frete || 'CIF')}`);

        const clientInfoHeight = doc.y - clientInfoY + blockPadding + 5;
        doc.strokeColor('#ccc')
            .lineWidth(1)
            .rect(pageLeftMargin, clientInfoY, clientColWidth * 2 + 10, clientInfoHeight)
            .stroke()
            .rect(pageLeftMargin + (clientColWidth * 2) + 20, clientInfoY, clientColWidth * 2, clientInfoHeight)
            .stroke();

        currentY = currentY + clientInfoHeight + 20;

        if (orcamento.observacao) {
            const observacaoText = `Observação: ${orcamento.observacao}`;
            const observacaoHeight = doc.heightOfString(observacaoText, {
                width: doc.page.width - pageLeftMargin - doc.page.margins.right,
                fontSize: 9,
            });

            doc.font('Helvetica-Bold').fontSize(10).text('Observação:', pageLeftMargin, currentY);
            doc.font('Helvetica').fontSize(9).text(safeText(orcamento.observacao), pageLeftMargin, doc.y + 4, {
                width: doc.page.width - pageLeftMargin - doc.page.margins.right,
                align: 'left',
                lineGap: 2,
            });

            currentY = doc.y + 10;
            doc.strokeColor('#ccc').lineWidth(1).rect(pageLeftMargin - 2, currentY - observacaoHeight - 18, doc.page.width - pageLeftMargin - doc.page.margins.right + 4, observacaoHeight + 18).stroke();
            currentY += 10;
        }

        // --- Tabela de Itens ---
        const colQuant = 0.08;
        const colCodCS = 0.12;
        const colDesc = 0.35;
        const colNCM = 0.15;
        const colUnit = 0.15;
        const colTotal = 0.15;
        const tableWidth = doc.page.width - doc.page.margins.left - doc.page.margins.right;
        const xPositions = [
            pageLeftMargin,
            pageLeftMargin + (colQuant * tableWidth),
            pageLeftMargin + ((colQuant + colCodCS) * tableWidth),
            pageLeftMargin + ((colQuant + colCodCS + colDesc) * tableWidth),
            pageLeftMargin + ((colQuant + colCodCS + colDesc + colNCM) * tableWidth),
            pageLeftMargin + ((colQuant + colCodCS + colDesc + colNCM + colUnit) * tableWidth)
        ];

        const headers = [
            { text: 'QUANT', width: colQuant * tableWidth, align: 'left' },
            { text: 'COD C&S', width: colCodCS * tableWidth, align: 'left' },
            { text: 'DESCRIÇÃO', width: colDesc * tableWidth, align: 'left' },
            { text: 'NCM', width: colNCM * tableWidth, align: 'left' },
            { text: 'VALOR UNIT', width: colUnit * tableWidth, align: 'right' },
            { text: 'TOTAL', width: colTotal * tableWidth, align: 'right' },
        ];

        let headerY = currentY;
        let cellPadding = 5;
        const defaultRowHeight = 20; // Altura padrão para linhas sem texto longo

        // Cabeçalho da tabela
        doc.font('Helvetica-Bold').fontSize(8);
        doc.fillColor('#f2f2f2')
            .rect(pageLeftMargin, headerY, tableWidth, defaultRowHeight)
            .fill();
        doc.fillColor('black');

        headers.forEach((header, i) => {
            doc.text(header.text, xPositions[i] + cellPadding, headerY + cellPadding, {
                width: header.width - (2 * cellPadding),
                align: header.align
            });
        });
        doc.strokeColor('#ccc').lineWidth(1).rect(pageLeftMargin, headerY, tableWidth, defaultRowHeight).stroke();

        currentY = headerY + defaultRowHeight;

        // Itens da tabela
        doc.font('Helvetica').fontSize(8);
        const itemsToDisplay = orcamento.items || [];
        const numEmptyRows = 5 - itemsToDisplay.length > 0 ? 5 - itemsToDisplay.length : 0;

        [...itemsToDisplay, ...Array(numEmptyRows).fill({})].forEach((item: any, index: number) => {
            // Calcular a altura da linha com base na descrição
            const descWidth = headers[2].width - (2 * cellPadding); // Largura da coluna DESCRIÇÃO
            const descText = item.descricao || '';
            const descHeight = descText
                ? doc.heightOfString(descText, { width: descWidth, fontSize: 8 })
                : defaultRowHeight - (2 * cellPadding);
            const rowHeight = Math.max(defaultRowHeight, descHeight + (2 * cellPadding));

            // Renderizar células
            doc.text(safeText(item.quantidade ? String(item.quantidade) : ''), xPositions[0] + cellPadding, currentY + cellPadding, {
                width: headers[0].width - (2 * cellPadding),
                align: 'left'
            });
            doc.text(safeText(item.codCS || ''), xPositions[1] + cellPadding, currentY + cellPadding, {
                width: headers[1].width - (2 * cellPadding),
                align: 'left'
            });
            doc.text(safeText(descText), xPositions[2] + cellPadding, currentY + cellPadding, {
                width: descWidth,
                align: 'left',
                lineBreak: true // Garante quebra de linha
            });
            doc.text(safeText(item.ncm || ''), xPositions[3] + cellPadding, currentY + cellPadding, {
                width: headers[3].width - (2 * cellPadding),
                align: 'left'
            });
            doc.text(safeText(item.valorUnitario ? `R$ ${formatCurrency(item.valorUnitario)}` : 'R$ 0,00'), xPositions[4] + cellPadding, currentY + cellPadding, {
                width: headers[4].width - (2 * cellPadding),
                align: 'right'
            });
            doc.text(safeText(item.total ? `R$ ${formatCurrency(item.total)}` : 'R$ 0,00'), xPositions[5] + cellPadding, currentY + cellPadding, {
                width: headers[5].width - (2 * cellPadding),
                align: 'right'
            });

            // Desenhar bordas da linha
            doc.strokeColor('#ccc').lineWidth(1);
            xPositions.forEach((xPos, colIndex) => {
                let width;
                if (colIndex < headers.length) {
                    width = headers[colIndex].width;
                } else {
                    width = (colIndex === xPositions.length - 1)
                        ? (pageRightMargin - xPos)
                        : (xPositions[colIndex + 1] - xPos);
                }
                doc.rect(xPos, currentY, width, rowHeight).stroke();
            });

            currentY += rowHeight;
        });

        currentY += 20;

        // --- Rodapé ---
        const footerY = currentY;
        const footerBlockHeight = 60;
        const footerBlockPadding = 5;

        doc.font('Helvetica-Bold').fontSize(12);
        doc.text(`Valor Total Produtos: R$ ${formatCurrency(orcamento.valorTotal)}`, pageLeftMargin, footerY, {
            align: 'left'
        });

        const fiscalY = footerY + 20;
        const fiscalWidth = tableWidth;
        doc.strokeColor('#ccc').lineWidth(1).rect(pageLeftMargin, fiscalY, fiscalWidth, footerBlockHeight).stroke();

        const fiscalColWidth = fiscalWidth / 4;
        const fiscalColPositions = [pageLeftMargin, pageLeftMargin + fiscalColWidth, pageLeftMargin + fiscalColWidth * 2, pageLeftMargin + fiscalColWidth * 3];
        for (let i = 1; i < 4; i++) {
            doc.moveTo(fiscalColPositions[i], fiscalY).lineTo(fiscalColPositions[i], fiscalY + footerBlockHeight).stroke();
        }

        doc.font('Helvetica').fontSize(10);
        const fiscalFields = [
            `CFOP: ${orcamento.cfop || '-----'}`,
            `ICMS: ${orcamento.valorIcms !== undefined ? (orcamento.valorIcms < 1 ? `${(orcamento.valorIcms * 100).toFixed(2)}` : ` ${orcamento.valorIcms.toFixed(2).replace('.', ',')}`) : '0,00'}%`,
            `IPI: ${orcamento.valorIpi !== undefined ? (orcamento.valorIpi < 1 ? `${(orcamento.valorIpi * 100).toFixed(2)}` : ` ${orcamento.valorIpi.toFixed(2).replace('.', ',')}`) : '0,00'}%`,
            `ISS: ${orcamento.valorIss !== undefined ? (orcamento.valorIss < 1 ? `${(orcamento.valorIss * 100).toFixed(2)}` : ` ${orcamento.valorIss.toFixed(2).replace('.', ',')}`) : '0,00'}%`
        ];
        fiscalFields.forEach((text, i) => {
            doc.text(text, fiscalColPositions[i] + cellPadding, fiscalY + cellPadding, {
                width: fiscalColWidth - (2 * cellPadding),
                align: 'left'
            });
        });

        doc.text('E-mail: cs2.usinagem@bol.com.br', pageRightMargin - 200, footerY, {
            align: 'right',
            width: 200
        });

        doc.strokeColor('#ccc')
            .lineWidth(1)
            .moveTo(pageLeftMargin, footerY - 10)
            .lineTo(pageRightMargin, footerY - 10)
            .stroke();

        doc.font('Helvetica').fontSize(8);
        doc.text(`Página ${doc._pageCount}`, pageRightMargin - 50, doc.page.height - 40, {
            align: 'right',
            width: 50
        });

        doc.end();
    });
}